const comparisonRange=document.querySelector(".comparison-range");const comparisonFrame=comparisonRange.closest(".comparison-frame");const beforeLabel=comparisonFrame.querySelector(".label-before");const afterLabel=comparisonFrame.querySelector(".label-after");function updateComparison(){const position=comparisonRange.valueAsNumber;comparisonFrame.style.setProperty("--split",position+"%");comparisonRange.setAttribute("aria-valuetext",position+"% изображения до чистки");const splitWidth=comparisonFrame.clientWidth*position/100;beforeLabel.style.visibility=splitWidth<beforeLabel.offsetWidth+16?"hidden":"visible";afterLabel.style.visibility=comparisonFrame.clientWidth-splitWidth<afterLabel.offsetWidth+16?"hidden":"visible"}comparisonRange.addEventListener("input",updateComparison);comparisonRange.hidden=false;updateComparison();new ResizeObserver(updateComparison).observe(comparisonFrame);